export class AddIdeaFolderComponent {
  private ideationService = inject(TopicIdeationService);
  public dialogRef = inject(DialogRef<AddIdeaFolderComponent>);
  public dialogData = inject<AddIdeaFolderDialogData>(DIALOG_DATA);

  form = new FormGroup({
    name: new FormControl('', [Validators.required, Validators.maxLength(254)]),
  });

  folders = signal<any[]>([]);
  selectedFolderIds = signal<Set<string>>(new Set());
  initialFolderIds = new Set<string>();
  loading = signal(false);
  loadingData = signal(true);
  showFolderInput = signal(false);

  allChecked = computed(() => {
    const currentFolders = this.folders();
    return currentFolders.length > 0 && this.selectedFolderIds().size === currentFolders.length;
  });

  constructor() {
    this.loadData();
  }

  private loadData() {
    this.loadingData.set(true);
    const params = {
      topicId: this.dialogData.topicId,
      ideationId: this.dialogData.ideationId,
    };

    forkJoin({
      allFolders: this.ideationService.getFolders(params),
      ideaFolders: this.ideationService.getIdeaFolders({ ...params, ideaId: this.dialogData.idea.id })
    }).pipe(take(1)).subscribe({
      next: (res) => {
        this.folders.set(res.allFolders.rows);
        const folderIds = res.ideaFolders.rows.map((f: any) => f.id);
        this.initialFolderIds = new Set(folderIds);
        this.selectedFolderIds.set(new Set(folderIds));
        this.loadingData.set(false);
      },
      error: (err) => {
        console.error('Error loading data', err);
        this.loadingData.set(false);
      }
    });
  }

  toggleFolder(folder: any) {
    const selected = new Set(this.selectedFolderIds());
    if (selected.has(folder.id)) {
      selected.delete(folder.id);
    } else {
      selected.add(folder.id);
    }
    this.selectedFolderIds.set(selected);
  }

  isFolderSelected(folder: any): boolean {
    return this.selectedFolderIds().has(folder.id);
  }

  toggleAllFolders() {
    if (this.allChecked()) {
      this.selectedFolderIds.set(new Set());
    } else {
      const allIds = this.folders().map(f => f.id);
      this.selectedFolderIds.set(new Set(allIds));
    }
  }

  save() {
    this.loading.set(true);
    const topicId = this.dialogData.topicId;
    const ideationId = this.dialogData.ideationId;
    const ideaId = this.dialogData.idea.id;

    const currentSelected = this.selectedFolderIds();
    const foldersToAdd = Array.from(currentSelected).filter(id => !this.initialFolderIds.has(id));
    const foldersToRemove = Array.from(this.initialFolderIds).filter(id => !currentSelected.has(id));

    const actions: any[] = [];

    // 1. Handle existing folder changes
    if (foldersToAdd.length > 0) {
      actions.push(this.ideationService.addFoldersToIdea({ topicId, ideationId, ideaId }, foldersToAdd));
    }

    // Legacy did one removal at a time, we'll follow that pattern for stability or use the existing service if it supports bulk?
    // Looking at service, removeIdeaFromFolder takes ONE idea and ONE folder.
    foldersToRemove.forEach(folderId => {
      actions.push(this.ideationService.removeIdeaFromFolder({ topicId, ideationId, folderId, ideaId }));
    });

    // 2. Handle new folder creation if requested
    if (this.showFolderInput() && this.form.valid) {
      actions.push(
        this.ideationService.createFolder({ topicId, ideationId, name: this.form.value.name! })
          .pipe(take(1), exhaustMap((folder) => {
            return this.ideationService.addIdeaToFolder({ topicId, ideationId, folderId: folder.id }, ideaId);
          }))
      );
    }

    if (actions.length > 0) {
      forkJoin(actions).pipe(take(1)).subscribe({
        next: () => this.dialogRef.close(true),
        error: (err) => {
          console.error('Error saving idea folders', err);
          this.loading.set(false);
          // Still close if something succeeded? Legacy closed on error too sometimes.
          this.dialogRef.close(true);
        }
      });
    } else {
      this.dialogRef.close(false);
    }
  }
}

// Helper to use exhaustMap in the forkJoin context if needed, but since it's a pipe on one of the items, it's fine.
import { exhaustMap } from 'rxjs/operators';

import { TestBed } from '@angular/core/testing';
import { describe, it, expect, vi, beforeEach } from 'vitest';
import { runInInjectionContext, EnvironmentInjector } from '@angular/core';
import { AddIdeaComponent } from './add-idea.component';
import { TopicIdeationService } from '../../../../../core/services/topic-ideation.service';
import { NotificationService } from '../../../../../core/services/notification.service';
import { of } from 'rxjs';
import { TranslateModule } from '@ngx-translate/core';

const mockTopic = { id: 't1', status: 'ideation', country: 'EE' } as any;
const mockIdeation = { id: 'i1', allowAnonymous: false, demographicsConfig: null } as any;

const mockCreatedIdea = { id: 'new-idea', status: 'published' } as any;
const mockIdeationService = {
  createIdea: vi.fn().mockReturnValue(of(mockCreatedIdea)),
  updateIdea: vi.fn().mockReturnValue(of(mockCreatedIdea)),
};
const mockNotification = { addError: vi.fn() };

describe('AddIdeaComponent', () => {
  let injector: EnvironmentInjector;

  beforeEach(() => {
    vi.clearAllMocks();
    TestBed.configureTestingModule({
      imports: [TranslateModule.forRoot()],
      providers: [
        { provide: TopicIdeationService, useValue: mockIdeationService },
        { provide: NotificationService, useValue: mockNotification },
      ],
    });
    injector = TestBed.inject(EnvironmentInjector);
  });

  function makeComp() {
    return runInInjectionContext(injector, () => {
      const comp = new AddIdeaComponent();
      (comp as any).topic = vi.fn().mockReturnValue(mockTopic);
      (comp as any).ideation = vi.fn().mockReturnValue(mockIdeation);
      return comp;
    });
  }

  it('should instantiate', () => {
    expect(makeComp()).toBeTruthy();
  });

  it('statement starts empty', () => {
    expect(makeComp().statement()).toBe('');
  });

  it('description starts empty', () => {
    expect(makeComp().description()).toBe('');
  });

  it('publish with empty fields sets errors and does not call service', () => {
    const comp = makeComp();
    comp.publish();
    expect(comp.errors()['statement']).toBeTruthy();
    expect(mockIdeationService.createIdea).not.toHaveBeenCalled();
  });

  it('publish with valid fields calls createIdea and emits ideaAdded', () => {
    const comp = makeComp();
    const emitSpy = vi.spyOn(comp.ideaAdded, 'emit');
    comp.onStatementChange('My statement');
    comp.onDescriptionChange('My description');
    comp.publish();
    expect(mockIdeationService.createIdea).toHaveBeenCalledWith(expect.objectContaining({
      topicId: 't1',
      ideationId: 'i1',
      statement: 'My statement',
      description: 'My description',
      status: 'published',
    }));
    expect(emitSpy).toHaveBeenCalledWith(mockCreatedIdea);
  });

  it('saveDraft calls createIdea with draft status', () => {
    const comp = makeComp();
    comp.onStatementChange('Draft title');
    comp.saveDraft();
    expect(mockIdeationService.createIdea).toHaveBeenCalledWith(expect.objectContaining({ status: 'draft' }));
  });

  it('close emits closed event', () => {
    const comp = makeComp();
    const emitSpy = vi.spyOn(comp.closed, 'emit');
    comp.close();
    expect(emitSpy).toHaveBeenCalled();
  });
});

import { ComponentFixture, TestBed } from '@angular/core/testing';
import { AddIdeasToFolderComponent } from './add-ideas-to-folder.component';
import { TranslateModule } from '@ngx-translate/core';
import { TopicIdeationService } from '../../../../../core/services/topic-ideation.service';
import { DIALOG_DATA, DialogRef } from '../../../../../shared/dialog';
import { of } from 'rxjs';
import { vi, describe, it, expect, beforeEach } from 'vitest';
import { Component, Input } from '@angular/core';
import { IconComponent } from '../../../../../shared/components/icon/icon.component';
import { NoopAnimationsModule } from '@angular/platform-browser/animations';

@Component({
  selector: 'cos-icon',
  standalone: true,
  template: ''
})
class MockIconComponent {
  @Input() name = '';
  @Input() size: number | string = 24;
}

describe('AddIdeasToFolderComponent', () => {
  let component: AddIdeasToFolderComponent;
  let fixture: ComponentFixture<AddIdeasToFolderComponent>;
  let mockIdeationService: any;
  let mockDialogRef: any;
  let mockDialogData: any;

  beforeEach(async () => {
    mockIdeationService = {
      getIdeas: vi.fn(),
      addIdeaToFolder: vi.fn().mockReturnValue(of({})),
      removeIdeaFromFolder: vi.fn().mockReturnValue(of({}))
    };
    mockDialogRef = { close: vi.fn() };
    mockDialogData = {
      topicId: 'topic1',
      ideationId: 'ideation1',
      folder: { id: 'folder1', name: 'Test Folder' }
    };

    // First call: all ideas. Second call: folder ideas.
    mockIdeationService.getIdeas.mockReturnValueOnce(of({
      rows: [
        { id: 'idea1', statement: 'Idea 1', votes: { up: { count: 1 } } },
        { id: 'idea2', statement: 'Idea 2', votes: { up: { count: 2 } } }
      ],
      count: 2
    })).mockReturnValueOnce(of({
      rows: [{ id: 'idea1', statement: 'Idea 1', votes: { up: { count: 1 } } }],
      count: 1
    }));

    await TestBed.configureTestingModule({
      imports: [
        AddIdeasToFolderComponent,
        TranslateModule.forRoot(),
        NoopAnimationsModule
      ],
      providers: [
        { provide: TopicIdeationService, useValue: mockIdeationService },
        { provide: DialogRef, useValue: mockDialogRef },
        { provide: DIALOG_DATA, useValue: mockDialogData }
      ]
    })
    .overrideComponent(AddIdeasToFolderComponent, {
        remove: { imports: [IconComponent] },
        add: { imports: [MockIconComponent] }
    })
    .compileComponents();

    fixture = TestBed.createComponent(AddIdeasToFolderComponent);
    component = fixture.componentInstance;
    fixture.detectChanges();
  });

  it('should create', () => {
    expect(component).toBeTruthy();
  });

  it('should load ideas and current folder assignments', () => {
    expect(component.ideas().length).toBe(2);
    expect(component.selectedIdeaIds().has('idea1')).toBe(true);
    expect(component.selectedIdeaIds().has('idea2')).toBe(false);
  });

  it('should add new ideas to folder', () => {
    component.toggleIdea({ id: 'idea2' } as any);
    component.addIdeas();
    expect(mockIdeationService.addIdeaToFolder).toHaveBeenCalledWith(
      expect.anything(),
      ['idea2']
    );
    expect(mockDialogRef.close).toHaveBeenCalledWith(true);
  });

  it('should remove ideas from folder', () => {
    component.toggleIdea({ id: 'idea1' } as any);
    component.addIdeas();
    expect(mockIdeationService.removeIdeaFromFolder).toHaveBeenCalled();
    expect(mockDialogRef.close).toHaveBeenCalledWith(true);
  });

  it('should close with false if no changes made', () => {
    component.addIdeas();
    expect(mockDialogRef.close).toHaveBeenCalledWith(false);
  });
});

import { Component, inject, signal, computed } from '@angular/core';
import { TranslateModule, TranslateService } from '@ngx-translate/core';
import { DIALOG_DATA, DialogRef } from '../../../../../shared/dialog';
import { TopicIdeationService } from '../../../../../core/services/topic-ideation.service';
import { IconComponent } from '../../../../../shared/components/icon/icon.component';
import { Idea } from '../../../../../core/interfaces/idea';
import { take, forkJoin } from 'rxjs';

interface IdeationFolderDialogData {
  topicId: string;
  ideationId: string;
  folder: any;
}

@Component({
  selector: 'app-add-ideas-to-folder',
  standalone: true,
  imports: [
    TranslateModule,
    IconComponent
  ],
  template: `
    <div class="overlay" (click)="dialogRef.close()" (keydown.enter)="dialogRef.close()" role="button" tabindex="0"></div>
    <div class="dialog_wrap">
      <div class="dialog">
        <div class="dialog_header ideation">
          <div class="header_text">
            <div class="title">{{ 'COMPONENTS.ADD_IDEAS_TO_FOLDER.HEADING' | translate }}</div>
            <div class="dialog_close">
              <button type="button" class="btn_dialog_close icon" (click)="dialogRef.close()" [aria-label]="'CONTROL.CLOSE' | translate">
                <cos-icon name="close"></cos-icon>
              </button>
            </div>
          </div>
        </div>
        <div class="dialog_content">
          <div class="content_section">
            <div class="section_content_wrap">
