    return this.topicService.canEdit(this.topic);
  }

  save() {
    const t = this.topic;
    const payload: any = {
      topicId: t.id,
      question: this.question(),
      deadline: this.deadline()
    };

    const save$ = t.discussionId
      ? this.discussionService.update(t.id, t.discussionId, payload)
