  private static readonly DEFAULT_PREFERENCES: NotificationPreferences = {
    Topic: false,
    Discussion: false,
    DiscussionComment: false,
    TopicDiscussion: false,
    CommentVote: false,
    TopicReport: false,
    TopicVoteList: false,
    TopicEvent: false,
