import { TestBed } from '@angular/core/testing';
import { of, Subject } from 'rxjs';
import { TopicVoteCastComponent } from './topic-vote-cast.component';
import { TopicService } from '../../../../../core/services/topic.service';
import { TopicVoteService } from '../../../../../core/services/topic-vote.service';
import { VoteDelegationService } from '../../../../../core/services/vote-delegation.service';
import { NotificationService } from '../../../../../core/services/notification.service';
import { DialogService } from '../../../../../shared/dialog/dialog.service';

const loadVote$ = new Subject<void>();

const mockTopicService = {
  STATUSES: { voting: 'voting', followUp: 'follow_up' },
  canUpdate: vi.fn(() => true),
  canDelete: vi.fn(() => true),
  reloadTopic: vi.fn(),
  patch: vi.fn(() => of({}))
};

const mockTopicVoteService = {
  loadVote$,
  VOTE_AUTH_TYPES: { hard: 'hard', soft: 'soft' },
  canVote: vi.fn(() => true),
  canDelegate: vi.fn(() => true),
  hasVoteEndedExpired: vi.fn(() => false),
  cast: vi.fn(() => of({})),
  update: vi.fn(() => of({})),
  get: vi.fn(() => of({ downloads: { bdocFinal: '/dl/bdoc', zipFinal: '/dl/zip' } })),
  reloadVote: vi.fn()
};

const mockVoteDelegationService = { delete: vi.fn(() => of({})) };
const mockNotification = { success: vi.fn(), error: vi.fn() };
const mockDialogAfterClosed = new Subject<any>();
const mockDialogService = {
  open: vi.fn(() => ({ afterClosed: () => mockDialogAfterClosed.asObservable() }))
};

const mockVote = {
  id: 'v1',
  authType: 'soft',
  maxChoices: 1,
  minChoices: 1,
  votersCount: 3,
  endsAt: null,
  reminderSent: false,
  downloads: {},
  options: {
    rows: [
      { id: 'o1', value: 'Yes', selected: false },
      { id: 'o2', value: 'No', selected: false }
    ]
  }
};

const mockTopic = {
  id: 't1',
  voteId: 'v1',
  status: 'voting',
  members: { users: { count: 5 } }
};

function buildComponent() {
  const comp = TestBed.runInInjectionContext(() => new TopicVoteCastComponent());
  (comp as any).vote = vi.fn().mockReturnValue(JSON.parse(JSON.stringify(mockVote)));
  (comp as any).topic = vi.fn().mockReturnValue({ ...mockTopic });
  comp.ngOnInit();
  return comp;
}

describe('TopicVoteCastComponent', () => {
  let component: TopicVoteCastComponent;

  beforeEach(() => {
    vi.clearAllMocks();
    TestBed.configureTestingModule({
      providers: [
        { provide: TopicService, useValue: mockTopicService },
        { provide: TopicVoteService, useValue: mockTopicVoteService },
        { provide: VoteDelegationService, useValue: mockVoteDelegationService },
        { provide: NotificationService, useValue: mockNotification },
        { provide: DialogService, useValue: mockDialogService }
      ]
    });
    component = buildComponent();
  });

  it('should create', () => {
    expect(component).toBeTruthy();
  });

  it('userHasVoted should be false when no option selected and no delegation', () => {
    expect(component.userHasVoted()).toBe(false);
  });

  it('userHasVoted should be true when an option is selected', () => {
    const vote = JSON.parse(JSON.stringify(mockVote));
    vote.options.rows[0].selected = true;
    (component as any).vote = vi.fn().mockReturnValue(vote);
    (component as any).checkUserVotingStatus();
    expect(component.userHasVoted()).toBe(true);
  });

  it('canSubmit should return true when one option selected (maxChoices=1)', () => {
    const vote = JSON.parse(JSON.stringify(mockVote));
    vote.options.rows[0].selected = true;
    (component as any).vote = vi.fn().mockReturnValue(vote);
    expect(component.canSubmit()).toBe(true);
  });

  it('canSubmit should return false when no options selected', () => {
    expect(component.canSubmit()).toBe(false);
  });

  it('selectOption should select an unselected option', () => {
    const vote = JSON.parse(JSON.stringify(mockVote));
    (component as any).vote = vi.fn().mockReturnValue(vote);
    component.selectOption(vote.options.rows[0]);
    expect(vote.options.rows[0].selected).toBe(true);
  });

  it('selectOption should deselect an already-selected option', () => {
    const vote = JSON.parse(JSON.stringify(mockVote));
    vote.options.rows[0].selected = true;
    (component as any).vote = vi.fn().mockReturnValue(vote);
    component.selectOption(vote.options.rows[0]);
    expect(vote.options.rows[0].selected).toBeUndefined();
  });

  it('doVote should call topicVoteService.cast for soft auth', () => {
    const vote = JSON.parse(JSON.stringify(mockVote));
    vote.options.rows[0].selected = true;
    (component as any).vote = vi.fn().mockReturnValue(vote);
    component.doVote();
    expect(mockTopicVoteService.cast).toHaveBeenCalledWith(expect.objectContaining({
      voteId: 'v1',
      topicId: 't1'
    }));
  });

  it('doVote should open sign dialog for hard auth', () => {
    const vote = JSON.parse(JSON.stringify(mockVote));
    vote.authType = 'hard';
    vote.options.rows[0].selected = true;
    (component as any).vote = vi.fn().mockReturnValue(vote);
    component.doVote();
    expect(mockDialogService.open).toHaveBeenCalled();
    expect(mockTopicVoteService.cast).not.toHaveBeenCalled();
  });

  it('closeVoting should open dialog', () => {
    component.closeVoting();
    expect(mockDialogService.open).toHaveBeenCalled();
  });

  it('sendVoteReminder should open dialog', () => {
    component.sendVoteReminder();
    expect(mockDialogService.open).toHaveBeenCalled();
  });

  it('editDeadline should open dialog', () => {
    component.editDeadline();
    expect(mockDialogService.open).toHaveBeenCalled();
  });

  it('delegate should open dialog when vote has no delegation', () => {
    const vote = JSON.parse(JSON.stringify(mockVote));
    (component as any).vote = vi.fn().mockReturnValue(vote);
    component.delegate();
    expect(mockDialogService.open).toHaveBeenCalled();
  });

  it('delegate should not open dialog when delegation already exists', () => {
    const vote = { ...JSON.parse(JSON.stringify(mockVote)), delegation: { id: 'u2', name: 'Bob' } };
    (component as any).vote = vi.fn().mockReturnValue(vote);
    component.delegate();
    expect(mockDialogService.open).not.toHaveBeenCalled();
  });

  it('doRevokeDelegation should open confirm dialog', () => {
    component.doRevokeDelegation();
    expect(mockDialogService.open).toHaveBeenCalled();
  });

  it('triggerFinalDownload should redirect when bdocFinal url is available', () => {
    const locationSpy = vi.spyOn(window, 'location', 'get').mockReturnValue({
      ...window.location,
      href: ''
    } as any);
    let href = '';
    Object.defineProperty(window, 'location', {
      value: { ...window.location, set href(val: string) { href = val; } },
      writable: true
    });
    const vote = { ...JSON.parse(JSON.stringify(mockVote)), downloads: { bdocFinal: '/dl/bdoc' } };
    (component as any).vote = vi.fn().mockReturnValue(vote);
    component.triggerFinalDownload('bdoc', false);
    expect(href).toBe('/dl/bdoc');
  });

  it('triggerFinalDownload should open dialog when no final download url', () => {
    component.triggerFinalDownload('bdoc', false);
    expect(mockDialogService.open).toHaveBeenCalled();
  });
});

import { Component, input, signal, inject, ChangeDetectionStrategy, OnInit } from '@angular/core';
import { DatePipe, UpperCasePipe } from '@angular/common';
import { TranslateModule } from '@ngx-translate/core';
import { take } from 'rxjs';
import { Topic } from '../../../../../core/interfaces/topic';
import { TopicService } from '../../../../../core/services/topic.service';
import { TopicVoteService } from '../../../../../core/services/topic-vote.service';
import { VoteDelegationService } from '../../../../../core/services/vote-delegation.service';
import { NotificationService } from '../../../../../core/services/notification.service';
import { DialogService } from '../../../../../shared/dialog/dialog.service';
import { ConfirmDialogComponent } from '../../../../../shared/components/confirm-dialog/confirm-dialog.component';
import { TopicVoteSignComponent } from '../topic-vote-sign/topic-vote-sign.component';
import { TopicVoteDeadlineComponent } from '../topic-vote-deadline/topic-vote-deadline.component';
import { TopicVoteDelegateComponent } from '../topic-vote-delegate/topic-vote-delegate.component';
import { TopicVoteReminderDialogComponent } from '../topic-vote-reminder-dialog/topic-vote-reminder-dialog.component';
import { DownloadVoteResultsComponent } from '../download-vote-results/download-vote-results.component';
import { CloseVotingComponent } from '../close-voting/close-voting.component';
import { BigGraphComponent } from '../big-graph/big-graph.component';
import { InitialsComponent } from '../../../../../shared/components/initials/initials.component';
import { IdeaDialogComponent } from '../idea-dialog/idea-dialog.component';
import { IconComponent } from '../../../../../shared/components/icon/icon.component';
import { CosDropdownDirective } from '../../../../../shared/directives/cos-dropdown.directive';
import { TooltipComponent } from '../../../../../shared/components/tooltip/tooltip.component';

@Component({
  selector: 'app-topic-vote-cast',
  standalone: true,
  changeDetection: ChangeDetectionStrategy.OnPush,
  imports: [TranslateModule, DatePipe, UpperCasePipe, BigGraphComponent, InitialsComponent, IconComponent, CosDropdownDirective, TooltipComponent],
  templateUrl: './topic-vote-cast.component.html',
  styleUrls: ['./topic-vote-cast.component.scss']
})
export class TopicVoteCastComponent implements OnInit {
  vote = input.required<any>();
  topic = input.required<Topic>();

  private topicService = inject(TopicService);
  private topicVoteService = inject(TopicVoteService);
  private voteDelegationService = inject(VoteDelegationService);
  private notification = inject(NotificationService);
  private dialogService = inject(DialogService);

  readonly VOTE_AUTH_TYPES = this.topicVoteService.VOTE_AUTH_TYPES;

  userHasVoted = signal(false);
  editVote = signal(false);

  constructor() {
    this.topicVoteService.loadVote$.subscribe(() => this.checkUserVotingStatus());
  }

  ngOnInit() {
    this.checkUserVotingStatus();
  }

  private checkUserVotingStatus() {
    const v = this.vote();
    const hasVoted = !!(v?.options?.rows?.some((o: any) => o.selected) || v?.delegation);
    this.userHasVoted.set(hasVoted);
    this.editVote.set(false);
  }

  canUpdate() {
    return this.topicService.canUpdate(this.topic());
  }

  canDelete() {
    return this.topicService.canDelete(this.topic());
  }

  canVote() {
    const t = this.topic();
    t.vote = this.vote();
    return this.topicVoteService.canVote(t);
  }

  canDelegate() {
    return this.topicVoteService.canDelegate(this.topic());
  }

  canSubmit() {
    const v = this.vote();
    if (!v?.options?.rows) return false;
    const selected = v.options.rows.filter((o: any) => o.selected);
    if (selected.length === 1 && (selected[0].value === 'Neutral' || selected[0].value === 'Veto')) return true;
    return selected.length <= v.maxChoices && selected.length >= v.minChoices;
  }

  canEditDeadline() {
    return this.topic().status === this.topicService.STATUSES.voting;
  }

  hasVoteEndedExpired() {
    return this.topicVoteService.hasVoteEndedExpired(this.topic(), this.vote());
  }

  selectOption(option: any) {
    if (!this.canVote()) return;
    const v = this.vote();
    if (option.selected) {
      delete option.selected;
      return;
    }
    v.options.rows.forEach((opt: any) => {
      if (option.value === 'Neutral' || option.value === 'Veto' || v.maxChoices === 1) {
        opt.selected = false;
      } else if (opt.value === 'Neutral' || opt.value === 'Veto') {
        opt.selected = false;
      }
    });
    option.optionId = option.id;
    const selected = v.options.rows.filter((o: any) => o.selected);
    const alreadySelected = selected.find((i: any) => i.id === option.id);
    if (selected.length >= v.maxChoices && !alreadySelected) return;
    option.selected = !option.selected;
  }

  doVote() {
    const v = this.vote();
    const options = v.options.rows.filter((o: any) => {
      o.optionId = o.id;
      return !!o.selected;
    });
    if (options.length > v.maxChoices || (options.length < v.minChoices && options[0]?.value !== 'Neutral' && options[0]?.value !== 'Veto')) {
      this.notification.error('MSG_ERROR_SELECTED_OPTIONS_COUNT_DOES_NOT_MATCH_VOTE_SETTINGS');
      return;
    }
    if (v.authType === this.VOTE_AUTH_TYPES.hard) {
      this.dialogService.open(TopicVoteSignComponent, { data: { topic: this.topic(), options } });
      return;
    }
    options.forEach((o: any) => { o.optionId = o.id; });
    this.topicVoteService.cast({ voteId: v.id, topicId: this.topic().id, options })
      .pipe(take(1))
      .subscribe({
        next: () => {
          this.notification.success('VIEWS.TOPICS_TOPICID.MSG_VOTE_REGISTERED');
          this.editVote.set(false);
          this.userHasVoted.set(true);
        }
      });
  }

  private saveVote(voteData?: any) {
    const v = Object.assign(voteData || this.vote(), { topicId: this.topic().id });
    this.topicVoteService.update(v).pipe(take(1)).subscribe({
      next: () => this.topicService.reloadTopic()
    });
  }

  closeVoting() {
    this.dialogService.open(CloseVotingComponent, { data: { topic: this.topic() } })
      .afterClosed().subscribe(value => {
        if (value) {
          const v = this.vote();
          v.endsAt = new Date();
          this.saveVote(v);
          const t = this.topic();
          t.status = this.topicService.STATUSES.followUp;
          this.topicService.patch(t).pipe(take(1)).subscribe(() => this.topicService.reloadTopic());
        }
      });
  }

  sendVoteReminder() {
    this.dialogService.open(TopicVoteReminderDialogComponent, { data: { topic: this.topic(), vote: this.vote() } })
      .afterClosed().subscribe(send => {
        if (send === true) {
          const v = this.vote();
          v.reminderTime = new Date();
          this.saveVote(v);
          this.topicVoteService.reloadVote();
          this.notification.success('COMPONENTS.TOPIC_VOTE_CAST.MSG_VOTE_REMINDER_SENT');
        }
      });
  }

  editDeadline() {
    this.dialogService.open(TopicVoteDeadlineComponent, { data: { vote: this.vote(), topic: this.topic() } });
  }

  delegate() {
    if (!this.vote().delegation) {
      this.dialogService.open(TopicVoteDelegateComponent, { data: { topic: this.topic() } });
    }
  }

  doRevokeDelegation() {
    this.dialogService.open(ConfirmDialogComponent, {
      data: {
        level: 'voting' as const,
        heading: 'MODALS.TOPIC_VOTE_REVOKE_DELEGATION_CONFIRM_HEADING',
        description: 'MODALS.TOPIC_VOTE_REVOKE_DELEGATION_CONFIRM_TXT_ARE_YOU_SURE',
        confirmBtn: 'MODALS.TOPIC_VOTE_REVOKE_DELEGATION_CONFIRM_YES',
        closeBtn: 'MODALS.TOPIC_VOTE_REVOKE_DELEGATION_CONFIRM_NO',
        svg: `<svg width="40" height="40" viewBox="0 0 40 40" fill="none" xmlns="http://www.w3.org/2000/svg">
          <path d="M26.3432 15.9229L27.0634 10L21.1505 10.7214L23.1001 12.6743L15.7221 20.0647L17.1292 21.4742L24.5072 14.0838L26.3432 15.9229Z" fill="#5AB467"/>
          <path d="M17.9282 29L28 18.9113L26.5929 17.5018L17.9352 26.174L13.4071 21.6524L12 23.0618L17.9282 29Z" fill="#5AB467"/>
          <path d="M27 27L32 32" stroke="#5AB467" stroke-width="4" stroke-linecap="square"/>
          <path d="M8 8L13 13" stroke="#5AB467" stroke-width="4" stroke-linecap="square"/>
          <rect x="2" y="2" width="36" height="36" rx="18" stroke="#5AB467" stroke-width="4"/>
          </svg>`
      }
    }).afterClosed().subscribe(result => {
      if (result === true) {
        const v = this.vote();
        this.voteDelegationService.delete({ topicId: this.topic().id, voteId: v.id })
          .pipe(take(1)).subscribe({
            next: () => {
              this.topicService.reloadTopic();
              this.userHasVoted.set(false);
            }
          });
      }
    });
  }

  triggerFinalDownload(type: string, includeCSV?: boolean) {
    const v = this.vote();
    if (v.downloads?.bdocFinal || v.downloads?.zipFinal) {
      let url = type === 'zip' ? (v.downloads?.zipFinal || '') : (v.downloads?.bdocFinal || '');
      if (!url) return;
      if (includeCSV) url += '&include[]=csv';
      window.location.href = url;
      return;
    }
    this.dialogService.open(DownloadVoteResultsComponent)
      .afterClosed().subscribe(allow => {
        if (allow === 'deadline') {
          this.editDeadline();
        } else if (allow === true) {
          const t = this.topic();
          t.status = this.topicService.STATUSES.followUp;
          this.topicService.patch(t).pipe(take(1)).subscribe(() => {
            this.topicService.reloadTopic();
            this.topicVoteService.get({ topicId: t.id, voteId: t.voteId }).pipe(take(1)).subscribe(vote => {
              let url = type === 'zip' ? (vote.downloads?.zipFinal || '') : (vote.downloads?.bdocFinal || '');
              if (!url) return;
              if (includeCSV) url += '&include[]=csv';
              window.location.href = url;
            });
          });
        }
      });
  }

  viewIdea(option: any) {
    const t = this.topic();
    if (!t.ideationId || !option.ideaId) return;
    this.dialogService.open(IdeaDialogComponent, {
      data: {
        topicId: t.id,
        ideationId: t.ideationId,
        ideaId: option.ideaId,
        topic: t,
      },
    });
  }

  voteGraphDasharray() {
    return `${2 * Math.PI * 20}px`;
  }

  voteGraphDashOffset(percentage: number) {
    return `${(2 * Math.PI * 20) * ((100 - percentage) / 100)}px`;
  }
}

import { Component, inject, signal, ChangeDetectionStrategy } from '@angular/core';
import { TranslateModule } from '@ngx-translate/core';
import { take } from 'rxjs';
import { DIALOG_DATA } from '../../../../../shared/dialog/dialog-tokens';
import { DialogCloseDirective, DialogRef } from '../../../../../shared/dialog/dialog-ref';
import { IconComponent } from '../../../../../shared/components/icon/icon.component';
import { DeadlinePickerComponent } from '../../../../../shared/components/deadline-picker/deadline-picker.component';
import { TopicVoteService } from '../../../../../core/services/topic-vote.service';
import { TopicService } from '../../../../../core/services/topic.service';
import { NotificationService } from '../../../../../core/services/notification.service';

@Component({
  selector: 'app-topic-vote-deadline',
  standalone: true,
  changeDetection: ChangeDetectionStrategy.OnPush,
  imports: [TranslateModule, DialogCloseDirective, DeadlinePickerComponent, IconComponent],
  templateUrl: './topic-vote-deadline.component.html'
})
export class TopicVoteDeadlineComponent {
  data = inject<{ vote: any; topic: any }>(DIALOG_DATA);
  private dialogRef = inject(DialogRef);
  private topicVoteService = inject(TopicVoteService);
  private topicService = inject(TopicService);
  private notification = inject(NotificationService);

  isNew = !this.data.vote.endsAt;
  deadline = signal<Date | null>(this.data.vote.endsAt ? new Date(this.data.vote.endsAt) : null);
  reminderTime = signal<Date | null>(this.data.vote.reminderTime ? new Date(this.data.vote.reminderTime) : null);

  onDeadlineChange(date: Date | null) {
    this.deadline.set(date);
  }

  onReminderChange(date: Date | null) {
    this.reminderTime.set(date);
  }

  save() {
    const vote = { ...this.data.vote, topicId: this.data.topic.id };
    if (this.deadline()) {
      vote.endsAt = this.deadline();
    }
    vote.reminderTime = this.reminderTime();
    this.topicVoteService.update(vote)
      .pipe(take(1))
      .subscribe({
        next: () => {
          this.topicService.reloadTopic();
          this.dialogRef.close();
        },
        error: (err) => {
          const errors = err?.errors || {};
          Object.values(errors).forEach((msg) => {
            if (typeof msg === 'string') this.notification.error(msg);
          });
        }
      });
  }
}

import { Component, inject, signal, ChangeDetectionStrategy } from '@angular/core';
import { FormsModule } from '@angular/forms';
import { TranslateModule, TranslateService } from '@ngx-translate/core';
import { debounceTime, distinctUntilChanged, of, Subject, switchMap, take } from 'rxjs';
import { toSignal } from '@angular/core/rxjs-interop';
import { DIALOG_DATA } from '../../../../../shared/dialog/dialog-tokens';
import { DialogCloseDirective, DialogRef } from '../../../../../shared/dialog/dialog-ref';
import { IconComponent } from '../../../../../shared/components/icon/icon.component';
import { TopicMemberUserService } from '../../../../../core/services/topic-member-user.service';
import { VoteDelegationService } from '../../../../../core/services/vote-delegation.service';
import { TopicService } from '../../../../../core/services/topic.service';
import { UserStore } from '../../../../../core/state/user.store';
import { NotificationService } from '../../../../../core/services/notification.service';

@Component({
  selector: 'app-topic-vote-delegate',
  standalone: true,
  changeDetection: ChangeDetectionStrategy.OnPush,
  imports: [TranslateModule, FormsModule, DialogCloseDirective, IconComponent],
  templateUrl: './topic-vote-delegate.component.html'
})
export class TopicVoteDelegateComponent {
  data = inject<{ topic: any }>(DIALOG_DATA);
  private dialogRef = inject(DialogRef);
  private memberUserService = inject(TopicMemberUserService);
  private voteDelegationService = inject(VoteDelegationService);
  private topicService = inject(TopicService);
  private userStore = inject(UserStore);
  private notification = inject(NotificationService);
  private translate = inject(TranslateService);

  searchStr = signal('');
  delegateUser = signal<any>(null);

  private search$ = new Subject<string>();

  searchResults = toSignal(
    this.search$.pipe(
      debounceTime(200),
      distinctUntilChanged(),
      switchMap(str => {
        if (!str || str.length < 2) return of([]);
        return this.memberUserService.query({ topicId: this.data.topic.id, search: str }).pipe(
          switchMap(res => {
            const me = this.userStore.user();
            const filtered = (res.rows || []).filter((u: any) => u.id !== me?.id);
            return of(filtered);
          })
        );
      })
    ),
    { initialValue: [] }
  );

  onSearch(event: Event) {
    const val = (event.target as HTMLInputElement).value;
    this.search$.next(val);
  }

  selectUser(user: any) {
    this.delegateUser.set(user);
    this.search$.next('');
    this.searchStr.set('');
  }

  removeDelegate() {
    this.delegateUser.set(null);
  }

  save() {
    const user = this.delegateUser();
    if (!user?.id) return;
    this.voteDelegationService.save({
      topicId: this.data.topic.id,
      voteId: this.data.topic.voteId || this.data.topic.vote?.id,
      userId: user.id
    }).pipe(take(1)).subscribe({
      next: () => {
        this.notification.success(this.translate.instant('MODALS.TOPIC_VOTE_DELEGATE_SUCCESS', { userName: user.name }));
        this.topicService.reloadTopic();
        this.dialogRef.close(true);
      },
      error: () => this.notification.error('MSG_ERROR_POST_API_USERS_TOPICS_VOTES_DELEGATIONS_40002')
    });
  }
}

import { vi, describe, it, expect, beforeEach } from 'vitest';
import { TestBed } from '@angular/core/testing';
import { TranslateModule } from '@ngx-translate/core';
import { TopicVoteReminderDialogComponent } from './topic-vote-reminder-dialog.component';
import { DIALOG_DATA } from '../../../../../shared/dialog/dialog-tokens';
import { DialogRef } from '../../../../../shared/dialog/dialog-ref';
import { UserStore } from '../../../../../core/state/user.store';

const mockUser = { id: 'u1', name: 'Alice' };
const mockUserStore = { user: vi.fn(() => mockUser) };

describe('TopicVoteReminderDialogComponent', () => {
  const futureDate = new Date(Date.now() + 3 * 24 * 60 * 60 * 1000).toISOString();
  let component: TopicVoteReminderDialogComponent;

  function setup(vote: any) {
    TestBed.configureTestingModule({
      providers: [
        { provide: DIALOG_DATA, useValue: { topic: { id: 't1' }, vote } },
        { provide: DialogRef, useValue: { close: vi.fn() } },
        { provide: UserStore, useValue: mockUserStore }
